import '../../domain/entities/explore_category.dart';
import '../../domain/entities/explore_metadata.dart';
import '../models/explore_content_model.dart';
import 'verified_media_registry.dart';

List<ExploreContentModel> getWorldFlagshipCatalog(String languageCode) {
  final locale = languageCode.trim().toLowerCase();
  return _items.map((e) => e.toModel(locale)).toList(growable: false);
}

class _WorldItem {
  const _WorldItem(this.id,this.countryCode,this.countryName,this.cityName,this.category,this.title,this.lat,this.lng);
  final String id,countryCode,countryName,cityName,title;
  final ExploreCategory category;
  final double lat,lng;

  ExploreContentModel toModel(String locale) {
    final type = _typeName(locale, category);
    final short = switch(locale) {
      'tr' => '$title · $cityName için seçilmiş $type keşfi.',
      'de' => '$title · kuratierte $type-Entdeckung in $cityName.',
      'fr' => '$title · découverte $type sélectionnée à $cityName.',
      'es' => '$title · experiencia de $type seleccionada en $cityName.',
      'it' => '$title · esperienza $type selezionata a $cityName.',
      'ar' => '$title · تجربة $type مختارة في $cityName.',
      _ => '$title · curated $type discovery in $cityName.',
    };
    final media = verifiedMediaFor(title);
    return ExploreContentModel(
      id:id,countryCode:countryCode,countryName:countryName,cityName:cityName,
      category:category,title:title,shortDescription:short,
      description:short,latitude:lat,longitude:lng,coverImageUrl:media?.imageUrl,
      tags:<String>['world_flagship_v5',category.value,countryCode.toLowerCase()],
      metadata:const ExploreMetadata(
        coordinatePrecision:'city_area',
        editorialStatus:'needs_exact_pin_review',
      ),
      galleryImageUrls:const [],isFeatured:category==ExploreCategory.place,
    );
  }
}

String _typeName(String locale, ExploreCategory c) {
  final en={ExploreCategory.place:'place',ExploreCategory.food:'food',ExploreCategory.snack:'snack',
    ExploreCategory.culture:'culture',ExploreCategory.drink:'drink',ExploreCategory.fruit:'regional product'};
  final tr={ExploreCategory.place:'mekan',ExploreCategory.food:'yemek',ExploreCategory.snack:'atıştırmalık',
    ExploreCategory.culture:'kültür',ExploreCategory.drink:'içecek',ExploreCategory.fruit:'yerel ürün'};
  return (locale=='tr'?tr:en)[c]!;
}

